const root=load("evidenceDir"),work=load("work"),data=load("planData");
const parse=r=>JSON.parse(r.content.find(x=>x.type==="text").text);
const eq=(a,b)=>JSON.stringify(sort(a))===JSON.stringify(sort(b));
function sort(x){return Array.isArray(x)?x.map(sort):x&&typeof x==="object"?Object.fromEntries(Object.keys(x).sort().map(k=>[k,sort(x[k])])):x;}
async function save(path,value){const r=await tools.apply_patch("*** Begin Patch\n*** Add File: "+root+"/"+path+"\n"+JSON.stringify(value,null,2).split("\n").map(x=>"+"+x).join("\n")+"\n*** End Patch");if(r?.isError)throw Error("evidence write failed");}
async function call(key,args,path){let r=await tools[key](args);await save(path,r);if(r.isError)throw Error("tool failed: "+key);return parse(r);}
async function offline(operation,extra){let r=await tools.exec_command({cmd:"$env:PYTHONPATH='"+work+"\\build\\validation\\hmd-python-deps'; python '"+root+"/direct-offline.py' '"+root+"' '"+work+"' "+operation+" "+extra,max_output_tokens:5000,yield_time_ms:10000});let output=r.output; while(r.session_id){r=await tools.write_stdin({session_id:r.session_id,chars:"",yield_time_ms:1000,max_output_tokens:5000});output+=r.output;}r.output=output;if(r.exit_code!==0)throw Error(r.output);return JSON.parse(r.output);}
for(let ordinal=load("nextOrdinal")||1;ordinal<=load("endOrdinal");ordinal++){
 if(load("activeTrackedToken")&&Date.now()+120000>load('trackingDeadline'))throw Error('pose hold deadline approaching');
 const step=data.schedule[ordinal-1],candidate=data.plan.candidateMapping[step.candidateId],desired=data.candidateConfigurations[step.candidateId],prefix="steps/"+String(ordinal).padStart(3,"0")+"/";
 let activeRecord=false,requestId=null,terminal=false;
 try{
  let status=await call("mcp__devbench_vr__communityshaders_renderscale",{action:"nr_status"},prefix+"before.json");
  if(status.producer.buildId!=="4385d3607500f6dd1006d3c90bd9a15b89eb193ab3795b4300b9155ec37c38e9")throw Error("CSX producer changed");
  let nr=status.neuralRendering;
  let fixed={...nr.requestedConfiguration.upscaling};delete fixed.neuralRenderingEnabled;
  if(!eq(fixed,data.plan.fixedSettings))throw Error("fixed graphics changed");
  if(load("lastOwnedConfiguration")&&!eq(nr.requestedConfiguration,load("lastOwnedConfiguration")))throw Error("configuration ownership changed");
  const current=nr.requestedConfiguration.color;
  function editableColor(value){let x=JSON.parse(JSON.stringify({settings:value.settings,experiments:value.experiments}));for(const p of ["upscaled_center","final_ldr_pre_ui"]){const z=x.experiments[p];x.experiments[p]={domain:z.domain,transform:z.transform,exposureMultiplier:z.exposureMultiplier,exposureSource:z.exposureSource};}return x;}
  if(!eq(editableColor(current),desired)){
   const color=await call("mcp__devbench_vr__communityshaders_nr_color",{action:"configure",expectedRevision:load("ownedRevision"),...desired},prefix+"configure-color.json");
   if(!color.ok||color.revision!==load("ownedRevision")+1||!eq(editableColor(color),desired))throw Error("colour acknowledgement inconsistent");
   store("ownedRevision",color.revision);
   status=await call("mcp__devbench_vr__communityshaders_renderscale",{action:"nr_status"},prefix+"after-color.json");nr=status.neuralRendering;
  }
  const enabled=(candidate.sourceCondition||candidate.condition)!=="nr_off";
  if(nr.requestedConfiguration.upscaling.neuralRenderingEnabled!==enabled){
   const mutation=await call("mcp__devbench_vr__communityshaders_renderscale",{action:"nr_configure",enabled,expectedConfigurationFingerprint:nr.requestedConfigurationFingerprint},prefix+"configure-master.json");
   if(!mutation.ok||mutation.neuralRendering.settings.enabled!==enabled)throw Error("NR master acknowledgement inconsistent");
  }
  status=await call("mcp__devbench_vr__communityshaders_renderscale",{action:"nr_status"},prefix+"applied.json");
  store("lastOwnedConfiguration",status.neuralRendering.requestedConfiguration);
  const expectedResult=await offline("expected",String(ordinal));
  if(!expectedResult.ok)throw Error("applied evidence failed: "+JSON.stringify(expectedResult.errors));
  const corr="nr-hmd-outdoor-20260916-s"+String(ordinal).padStart(3,"0");
  const rec=await call("mcp__devbench_vr__record",{action:"start",correlationId:corr,intervalMs:50,maximumDurationMs:120000},prefix+"record-start.json");
  if(rec.recording!==true||rec.correlationId!==corr)throw Error("record start mismatch");activeRecord=true;store("activeRecordCorrelation",corr);
  const capture={...load("captureDescriptor"),destination:{policy:"absolute",directory:root+"/"+prefix+"frames",baseName:"frame",overwrite:"never"},tags:{captureInteractionSessionId:corr}};
  const started=await call("mcp__devbench_vr__communityshaders_screenshot",{action:"sequence_start",contractMajor:1,clientId:"nr-colour-assessment",commandId:corr+"-start",sequence:{frameCount:12,useSettings:false,schedule:{basis:"wall_clock",intervalMs:500,startDelayMs:0,pausePolicy:"hold"},backpressure:{policy:"skip",maximumConsecutiveSkips:20},failurePolicy:"continue",capture,packaging:{frameManifest:true,previewVideo:{requested:false,required:false,framesPerSecond:2}}}},prefix+"capture-start.json");
  if(!started.ok||!started.result.requestId)throw Error("capture not accepted");
  requestId=started.result.requestId;store("activeScreenshotRequest",requestId);
  let receipt;
  const deadline=Date.now()+60000;
  for(let poll=0;Date.now()<deadline;poll++){
   await new Promise(r=>setTimeout(r,poll===0?6500:500));
   const got=await call("mcp__devbench_vr__communityshaders_screenshot",{action:"request_get",requestId,contractMajor:1,clientId:"nr-colour-assessment",commandId:corr+"-get-"+poll},prefix+"capture-get-"+poll+".json");
   receipt=got.result;
   if(["completed","completed_with_warnings","failed","failed_partial","stopped","cancelled","cancelled_partial","rejected"].includes(receipt.state)){terminal=true;break;}
  }
  if(!terminal)throw Error("capture completion timeout");
  store("activeScreenshotRequest",null);
  const manifest=receipt.artifacts.find(x=>x.path===receipt.manifest.finalPath);
  if(!manifest)throw Error("no committed sequence manifest");
  const stamps=await offline("stamps","'"+manifest.path+"'");
  const diagnostics=await call("mcp__devbench_vr__communityshaders_nr_color",{action:"capture_diagnostics",stamps:stamps.stamps},prefix+"exposure-raw.json");
  await save(prefix+"capture-diagnostics.json",diagnostics);
  const recording=await call("mcp__devbench_vr__record",{action:"stop",expectedCorrelationId:corr},prefix+"record-stop.json");activeRecord=false;store("activeRecordCorrelation",null);
  const after=await call("mcp__devbench_vr__communityshaders_renderscale",{action:"nr_status"},prefix+"after.json");
  if(!eq(after.neuralRendering.requestedConfiguration,load("lastOwnedConfiguration")))throw Error("configuration changed during capture");
  const dr=await tools.exec_command({cmd:"$p='"+root+"/"+prefix+"capture-diagnostics.json'; [pscustomobject]@{path=$p;bytes=(Get-Item -LiteralPath $p).Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()} | ConvertTo-Json -Compress",max_output_tokens:300});
  const entry={scheduleOrdinal:ordinal,expected:expectedResult.expected,captureSessionDirectory:root+"/"+prefix,captureSessionId:corr,manifest,terminalReceipt:receipt,captureDiagnostics:diagnostics,captureDiagnosticsArtifact:JSON.parse(dr.output),recording,transport:"direct_mcp",userSessionAuthorization:load("userSessionAuthorization")};
  await save(prefix+"entry.json",entry);
  const checked=await offline("validate",String(ordinal));await save(prefix+"validation.json",checked);
  if(!checked.ok)throw Error("evidence validation failed: "+JSON.stringify(checked));
  store("nextOrdinal",ordinal+1);
  text({completed:ordinal,total:data.schedule.length,pairs:checked.validatedPairs,role:step.role});
  await yield_control();
 }catch(e){
  const error=String(e);store("campaignFailure",{ordinal,error,activeRecord,requestId,terminal});await save(prefix+"failure.json",{ordinal,error,activeRecord,requestId,terminal});text(load("campaignFailure"));
  if(requestId&&!terminal){const stopped=await tools.mcp__devbench_vr__communityshaders_screenshot({action:"sequence_stop",requestId,contractMajor:1,clientId:"nr-colour-assessment",commandId:"failure-stop-"+ordinal});await save(prefix+"failure-sequence-stop.json",stopped);}
  if(activeRecord){const corr=load("activeRecordCorrelation");const r=await tools.mcp__devbench_vr__record({action:"stop",expectedCorrelationId:corr});await save(prefix+"failure-record-stop.json",r);store("activeRecordCorrelation",null);}
  break;
 }
}

import sys,json
from pathlib import Path
root,checkout=Path(sys.argv[1]),Path(sys.argv[2]); operation=sys.argv[3]
sys.path.insert(0,str(checkout/"tools/nr-color"))
import hmd_assess as h,hmd_capture as c,assess
plan=h.read_json(root/"private-plan.json")
assert h.digest(root/"private-plan.json")==h.read_json(root/"campaign-index.json")["planSha256"]
def payload(p):return json.loads(h.read_json(p)["content"][0]["text"])
if operation=="stamps":
 m=h.read_json(Path(sys.argv[4]));stamps={}
 for child in m["children"]:
  nr=child["actual"]["acquisition"].get("nrEvidence",{})
  for obs in [nr.get("engineExposure",{})]+[nr.get(e,{}).get("exposure",{}) for e in h.EYES]:
   if all(isinstance(obs.get(k),int) and obs[k]>0 for k in ("frame","epoch","sequence")):
    stamp={k:obs[k] for k in ("frame","epoch","sequence")};stamps[tuple(stamp.values())]=stamp
 print(json.dumps({"stamps":list(stamps.values())}))
elif operation=="expected":
 number=int(sys.argv[4]); suffix=sys.argv[5] if len(sys.argv)>5 else ""; nr=payload(root/f"steps/{number:03}{suffix}/applied.json")["neuralRendering"]
 candidate=plan["candidateMapping"][plan["schedule"][number-1]["candidateId"]]
 color=nr["requestedConfiguration"]["color"]
 expected={"configuration":nr["requestedConfiguration"],"configurationFingerprint":nr["requestedConfigurationFingerprint"],"insertion":"upscaled_center","maximumRenderFrameAge":0,"requiresCapturedExposure":False,"exposureAge":0}
 errors=[]
 for pair in nr["captureEvidence"]["routes"]:
  try:
   expected.update(colorRevision=pair["left"]["colorRevision"],inputEpoch=pair["left"]["inputEpoch"])
   h.check_nr(pair,expected,candidate,{"engineFrame":max(pair[e]["frame"] for e in h.EYES)},require_exposure=False)
   scout=h.read_json(Path(payload(root/"scout4Get.json")["result"]["manifest"]["finalPath"]))
   expected["planes"]={p["eye"]:p for p in scout["children"][0]["actual"]["acquisition"]["planes"]}
   print(json.dumps({"ok":True,"expected":expected}));break
  except Exception as e:errors.append(str(e))
 else:print(json.dumps({"ok":False,"errors":errors}))
elif operation=="validate":
 number=int(sys.argv[4]);suffix=sys.argv[5] if len(sys.argv)>5 else "";entry=h.read_json(root/f"steps/{number:03}{suffix}/entry.json")
 index=h.read_json(root/"campaign-index.json");errors=[];pairs=[]
 manifest=h.read_json(h.committed(entry["manifest"],root))
 candidate=plan["candidateMapping"][plan["schedule"][number-1]["candidateId"]]
 try:
  h.require(manifest["producer"]==index["producer"] and manifest["sessionId"]==index["sessionId"],"producer/session changed")
  h.require(manifest["state"]=="final" and manifest["counts"]["inFlight"]==0,"sequence not final")
  for child in manifest["children"]:
   try:
    pair=h.check_pair(child,Path(entry["manifest"]["path"]).parent,entry["expected"],candidate,plan["regionPolicy"],capture_diagnostics=entry["captureDiagnostics"],sequence=manifest)
    h.check_camera(pair["acquisition"],plan["fixedScene"])
    pairs.append(pair)
   except Exception as e:errors.append({"ordinal":child["ordinal"],"error":str(e)})
  entry["validatedPairs"]=len(pairs);entry["excludedChildren"]=errors
  entry["motionEvidence"]=c.acquisition_motion(pairs,plan)
  recording=entry["recording"]
  source=Path("D:/Skyrim Mods/mods/Synthesis Patch (SFW)/SKSE/Plugins/devbench/recordings")/Path(recording["path"]).name
  recording["artifacts"]=[h.preserve(source,root/f"recordings/{number:03}.json")]
  entry["recordedScene"]=h.recording_scene(h.read_json(source),plan)
  h.require(recording["meta"]["correlationId"]==entry["captureSessionId"],"record correlation differs")
  h.require(recording["limitReached"] is False and recording["unrecordedTailMs"]==0,"incomplete recording")
  h.require(entry["recordedScene"]["qualified"],entry["recordedScene"]["reason"])
  h.require(len(pairs)>=12,"insufficient accepted pairs")
  h.require(entry["motionEvidence"]["available"],entry["motionEvidence"]["reason"])
 except Exception as e:entry["error"]=str(e)
 index["sequences"].append(entry);assess.atomic_json(root/"campaign-index.json",index)
 result={"ok":not entry.get("error"),"validatedPairs":len(pairs),"errors":errors,"error":entry.get("error")}
 if number==3 and result["ok"]:
  baseline=c.baseline_repeatability(index["sequences"],plan)
  h.save_json(root/"baseline-repeatability-gate.json",baseline)
  result.update(ok=baseline["qualified"],baselineExclusionCount=len(baseline["excluded"]),baselineGatePath=str(root/"baseline-repeatability-gate.json"))
  if not baseline["qualified"]:result["error"]="unchanged baselines are motion/exposure confounded"
 print(json.dumps(result))

